List<int>? _decodeTable;
Map<int, int>? _encodeTable;

void _ensureInit() {
  if (_decodeTable != null) return;
  final blob = base64.decode(_gbkTableBase64.replaceAll(RegExp(r'\s'), ''));
  final decode = List<int>.filled(65536, -1);
  final encode = <int, int>{};
  for (var i = 0; i + 5 <= blob.length; i += 5) {
    final lead = blob[i];
    final trail = blob[i + 1];
    final cp = (blob[i + 2] << 16) | (blob[i + 3] << 8) | blob[i + 4];
    final key = (lead << 8) | trail;
    decode[key] = cp;
    encode.putIfAbsent(cp, () => key);
  }
  _decodeTable = decode;
  _encodeTable = encode;
}

String gbkDecode(List<int> bytes) {
  _ensureInit();
  final table = _decodeTable!;
  final buf = StringBuffer();
  var i = 0;
  while (i < bytes.length) {
    final b = bytes[i];
    if (b < 0x80) {
      buf.writeCharCode(b);
      i++;
    } else if (b >= 0x81 && b <= 0xFE && i + 1 < bytes.length) {
      final key = (b << 8) | bytes[i + 1];
      final cp = key < table.length ? table[key] : -1;
      buf.writeCharCode(cp >= 0 ? cp : 0xFFFD);
      i += 2;
    } else {
      buf.writeCharCode(0xFFFD);
      i++;
    }
  }
  return buf.toString();
}

List<int> gbkEncode(String text) {
  _ensureInit();
  final table = _encodeTable!;
  final out = <int>[];
  for (final cp in text.runes) {
    if (cp < 0x80) {
      out.add(cp);
    } else {
      final key = table[cp];
      if (key != null) {
        out.add((key >> 8) & 0xFF);
        out.add(key & 0xFF);
      } else {
        out.add(0x3F);
      }
    }
  }
  return out;
}

String gbkPercentEncode(String text) {
  final bytes = gbkEncode(text);
  final buf = StringBuffer();
  for (final b in bytes) {
    if ((b >= 0x30 && b <= 0x39) ||
        (b >= 0x41 && b <= 0x5A) ||
        (b >= 0x61 && b <= 0x7A)) {
      buf.writeCharCode(b);
    } else {
      final hex = b.toRadixString(16).padLeft(2, '0').toUpperCase();
      buf.write('%');
      buf.write(hex);
    }
  }
  return buf.toString();
}
